    console.assert(JSON.stringify(candidate([11, 22, 33, 44], [33, 44])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([100, 200, 300, 400, 500, 600, 700, 800, 900, 1000], [120, 150, 180, 210])) === JSON.stringify(10));
    console.assert(JSON.stringify(candidate([13, 26, 39, 52, 65], [52, 65])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([500, 500, 500, 500, 500, 500, 500, 500, 500, 500], [1000, 1500, 2000])) === JSON.stringify(2500));
}
